import jakarta.persistence.*;

@Entity
@Table(name = "customers")
public class Customer {
    @Id  // Marks this as the primary key
    @GeneratedValue(strategy = GenerationType.IDENTITY)  // Auto-increment
    private Long id;

    @Column(nullable = false)
    private String name;

    @Column(unique = true, nullable = false)  // Unique constraint but NOT primary key
    private String email;

    // Constructors, getters, setters
}

// Composite primary key example
@Entity
@Table(name = "order_items")
@IdClass(OrderItemId.class)  // Reference to composite key class
public class OrderItem {
    @Id
    private Long orderId;  // Part of composite key

    @Id
    private Long productId;  // Part of composite key

    private Integer quantity;
}

import jakarta.persistence.*;

@Entity
@Table(name = "orders")
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)  // Many orders belong to one customer
    @JoinColumn(name = "customer_id", nullable = false)  // FK column name
    private Customer customer;  // This creates the foreign key relationship

    private Double totalAmount;
}

