import jakarta.persistence.*;
import java.io.Serializable;

// Composite key class must implement Serializable and override equals/hashCode
public class OrderItemId implements Serializable {
    private Long orderId;
    private Long productId;

    // Must override equals and hashCode for composite key to work
    @Override
    public boolean equals(Object o) { /* compare both fields */ }
    @Override
    public int hashCode() { /* hash both fields */ }
}

@Entity
@Table(name = "order_items")
@IdClass(OrderItemId.class)  // Tell JPA this entity uses a composite key
public class OrderItem {
    @Id
    @Column(name = "order_id")
    private Long orderId;  // First part of composite key

    @Id
    @Column(name = "product_id")
    private Long productId;  // Second part of composite key

    private Integer quantity;  // Regular column, not part of key
    private Double price;
}

import jakarta.persistence.*;

@Entity
@Table(name = "orders", indexes = {
    @Index(name = "idx_orders_customer_id", columnList = "customer_id")  // Explicit index in JPA
})
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "customer_id", nullable = false)  // FK column
    private Customer customer;

    private Double totalAmount;
}

