import jakarta.persistence.*;

@Entity
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne
    @JoinColumn(name = "customer_id", nullable = false)  // FK constraint enforces integrity
    private Customer customer;
}

// This INSERT will be REJECTED by the database:
var order = new Order();
var fakeCustomer = new Customer();
fakeCustomer.setId(9999L);  // Customer 9999 doesn't exist
order.setCustomer(fakeCustomer);
orderRepo.save(order);  // Throws DataIntegrityViolationException

// This DELETE will be REJECTED if orders reference customer 5:
customerRepo.deleteById(5L);  // Throws ConstraintViolationException

// This UPDATE will be REJECTED:
var order = orderRepo.findById(1L).get();
var nonexistent = new Customer();
nonexistent.setId(8888L);  // No such customer
order.setCustomer(nonexistent);  // DB rejects the update
